INSERT INTO section_responses (group_id, section_id, content_json, version, updated_by)
VALUES (5, 7, '{"synthesisNote":"Le diagnostic logistique met en evidence une pression croissante sur l''acheminement du courrier et des colis, liee au vieillissement du parc de transport et a l''absence d''outil de planification des tournees. Les priorites sont la modernisation du parc logistique, la digitalisation de la planification des tournees et un meilleur maillage entre centres de tri et reseau commercial.","stakeholders":[],"pestel":[],"swot":{"strengths":[],"weaknesses":[],"opportunities":[],"threats":[]},"causalAnalysis":[]}', 1, (SELECT id FROM users WHERE username = 'dir.logistique'))
