VALUES (5, 17, '{"vision":"Garantir une chaine logistique moderne, fiable et agile, condition de la qualite de service de SENICO sur l''ensemble du territoire et face a la croissance du e-commerce.","axes":[{"axisCode":"AXE1","orientations":[{"label":"Elaborer un plan pluriannuel de renouvellement du parc logistique","actions":[{"label":"Diagnostiquer le parc existant et prioriser les besoins de renouvellement","constraintsOrOpportunities":"Contrainte : budget limite pour un renouvellement complet du parc. Opportunite : soutien national a la modernisation des infrastructures logistiques."}]},{"label":"Acquerir des vehicules et equipements de tri modernises","actions":[{"label":"Lancer les appels d''offres et acquerir les vehicules/equipements prioritaires","constraintsOrOpportunities":"Contrainte : budget limite pour un renouvellement complet du parc. Opportunite : soutien national a la modernisation des infrastructures logistiques."}]}]},{"axisCode":"AXE2","orientations":[{"label":"Deployer un outil de planification et de suivi des tournees","actions":[{"label":"Selectionner et deployer un outil de planification et de suivi des tournees","constraintsOrOpportunities":"Contrainte : absence actuelle d''outil de planification des tournees. Opportunite : solutions technologiques de suivi logistique disponibles."}]},{"label":"Optimiser les circuits d''acheminement inter-centres","actions":[{"label":"Revoir et optimiser les circuits d''acheminement entre centres","constraintsOrOpportunities":"Contrainte : absence actuelle d''outil de planification des tournees. Opportunite : solutions technologiques de suivi logistique disponibles."}]}]},{"axisCode":"AXE3","orientations":[{"label":"Renforcer la capacite des centres de tri prioritaires","actions":[{"label":"Investir dans les equipements et le personnel des centres de tri prioritaires","constraintsOrOpportunities":"Contrainte : maillage territorial actuellement insuffisant. Opportunite : mutualisation possible des moyens d''exploitation avec la Direction Technique."}]},{"label":"Etendre le maillage des points de collecte et entrepots relais","actions":[{"label":"Identifier et ouvrir de nouveaux points de collecte et entrepots relais","constraintsOrOpportunities":"Contrainte : maillage territorial actuellement insuffisant. Opportunite : mutualisation possible des moyens d''exploitation avec la Direction Technique."}]}]},{"axisCode":"AXE4","orientations":[{"label":"Adapter les capacites logistiques a la croissance des colis e-commerce","actions":[{"label":"Dimensionner les capacites logistiques selon la demande e-commerce previsionnelle","constraintsOrOpportunities":"Contrainte : croissance rapide et peu anticipee des volumes de colis. Opportunite : croissance du e-commerce et de la livraison."}]},{"label":"Nouer des partenariats logistiques avec les acteurs du e-commerce","actions":[{"label":"Prospecter et contractualiser avec des acteurs du e-commerce et de la livraison","constraintsOrOpportunities":"Contrainte : croissance rapide et peu anticipee des volumes de colis. Opportunite : croissance du e-commerce et de la livraison."}]}]}]}', 1, (SELECT id FROM users WHERE username = 'dir.logistique'))
